"""UI strings in English and Uzbek (Latin script). `tr(key, lang, **fmt)` falls back to English.

Every Uzbek string was written by the AI assistant and must be reviewed by a native speaker: see docs/uzbek_review.md
(generated by scripts/uzbek_review.py), where strings the author is unsure about carry a reason (`unsure=`).
Crop names come from `crop_name`; dataset and product names (NASA POWER, MODIS, SMAP, SoilGrids) are never translated.
The long evidence / gaps / risks bullets inside the option cards are English only (the UI says so in Uzbek mode).
"""
from __future__ import annotations

LANGS = {"en": "English", "uz": "O'zbekcha"}

S: dict[str, dict[str, str]] = {}
UNSURE: dict[str, str] = {}      # key -> why the Uzbek text may be wrong


def add(key: str, en: str, uz: str | None = None, unsure: str | None = None) -> None:
    S[key] = {"en": en, **({"uz": uz} if uz else {})}
    if unsure:
        UNSURE[key] = unsure


def tr(key: str, lang: str = "en", **fmt) -> str:
    entry = S[key]
    text = entry.get(lang) or entry["en"]
    return text.format(**fmt) if fmt else text


MONTHS = {"en": ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"],
          "uz": ["Yan", "Fev", "Mar", "Apr", "May", "Iyn", "Iyl", "Avg", "Sen", "Okt", "Noy", "Dek"]}

# crop names: English comes from crops.json; Uzbek below (qualifiers in brackets kept)
CROP_UZ: dict[str, tuple[str, str | None]] = {
    "cotton": ("Paxta", None), "winter_wheat": ("Kuzgi bug'doy", None), "barley": ("Kuzgi arpa", None),
    "maize": ("Makkajo'xori (don uchun)", None), "sorghum": ("Jo'xori (sorgo)", "check sorghum vs jo'xori usage"),
    "millet": ("Tariq", None), "alfalfa": ("Beda (1 yillik ekin sifatida modellashtirilgan)", None),
    "mung_bean": ("Mosh", None), "chickpea": ("No'xat (bahorda ekiladi)", None), "lentil": ("Yasmiq (bahorda ekiladi)", None),
    "soybean": ("Soya", None), "sunflower": ("Kungaboqar", None),
    "safflower": ("Aspir", "safflower: 'aspir' vs another local name"), "rapeseed": ("Kuzgi raps", "rapeseed: 'raps' vs 'kolza'"),
    "rye_cover": ("Kuzgi javdar (qoplama ekin)", "'qoplama ekin' for cover crop; 'siderat' also used"),
    "hairy_vetch": ("Tukli vika (qoplama ekin)", "'tukli vika' for hairy vetch"),
    "clover": ("Sebarga / berseem (qoplama ekin)", "clover vs berseem clover naming"),
    "potato": ("Kartoshka", None), "melon": ("Qovun", None), "sugar_beet": ("Qand lavlagi", None),
}


def crop_name(crop_id: str, lang: str, english: str) -> str:
    return CROP_UZ.get(crop_id, (english, None))[0] if lang == "uz" else english


